 index = 372;
 break;
 case 4:
 index = 392;
 break;
 }
 if (this.mineRandom.NextDouble() < 0.005) {
 index = 797;
 } else if (this.mineRandom.NextDouble() < 0.08) {
 index = 394;
 }
 } else {
 index = 86;
 }
 break;
 case 40:
 if (this.GetAdditionalDifficulty() > 0 && this.mineLevel % 40 < 30) {
 switch (this.mineRandom.Next(4)) {
 case 0:
 case 3:
 index = 259;
 break;
 case 1:
 index = 404;
 break;
 case 2:
 index = 420;
 break;
 }
 if (this.mineRandom.NextDouble() < 0.08) {
